// Singleton DOI objects, with independent basic/clinical rating profiles. No network.
export const DB_NAME='research-radar-personal';let connection;
export const normalizeDOI=s=>String(s||'').trim().replace(/^(https?:\/\/(dx\.)?doi\.org\/|doi:\s*)/i,'').toLowerCase();
export function noteKey(p){const doi=normalizeDOI(p.doi);if(doi)return 'doi:'+doi;if(!p.id)throw Error('文章缺少 DOI 或来源 ID');return 'source:'+p.id;}
export const profileOf=(n,radar)=>n?.profiles?.[radar]||{relevance:0,inspiration:0,reasons:[],lowReason:''};
export function linkRadar(note,radar){const n=structuredClone(note);n.radars=[...new Set([...n.radars,radar])];return n;}
export function snapshot(p){return Object.fromEntries(['id','doi','title','abstract','journal','journalId','date','url','authors','sources','topics','transferMechanisms','evidenceScope','studyType'].filter(k=>p[k]!==undefined).map(k=>[k,structuredClone(p[k])]));}
export function emptyNote(article,radar){const now=new Date().toISOString();return {key:noteKey(article),doi:normalizeDOI(article.doi),radars:[radar],article:snapshot(article),favorite:true,folder:'',tags:[],readStatus:'unread',profiles:{[radar]:{relevance:0,inspiration:0,reasons:[],lowReason:'',updatedAt:now}},annotations:'',methods:'',hypotheses:'',questions:'',createdAt:now,updatedAt:now};}
export function openDB(){if(connection)return Promise.resolve(connection);return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{r.result.createObjectStore('notes',{keyPath:'key'});r.result.createObjectStore('preferences',{keyPath:'radar'});};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('数据库被旧标签页阻塞，请关闭其他页面后重试'));r.onsuccess=()=>{connection=r.result;connection.onversionchange=closeDB;resolve(connection);};});}
export function closeDB(){connection?.close();connection=undefined;}
async function transaction(stores,mode,run){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(stores,mode);let value;try{value=run(tx);}catch(e){tx.abort();reject(e);return;}tx.oncomplete=()=>resolve(typeof value==='function'?value():value);tx.onerror=()=>reject(tx.error||Error('本地保存失败'));tx.onabort=()=>reject(tx.error||Error('操作已取消'));});}
export async function allNotes(){return transaction(['notes'],'readonly',tx=>{const r=tx.objectStore('notes').getAll();return()=>r.result;});}
export async function allPreferences(){return transaction(['preferences'],'readonly',tx=>{const r=tx.objectStore('preferences').getAll();return()=>r.result;});}
export async function saveNote(n){const valid=validateNote(n);return transaction(['notes'],'readwrite',tx=>{tx.objectStore('notes').put(valid);return valid;});}
export async function deleteNote(key){return transaction(['notes'],'readwrite',tx=>tx.objectStore('notes').delete(key));}
export async function savePreference(p){const valid=validatePreference(p);return transaction(['preferences'],'readwrite',tx=>tx.objectStore('preferences').put(valid));}
function str(v,name,max=50000){if(typeof v!=='string'||v.length>max)throw Error(`${name}格式或长度不合法`);return v;}
function strings(v,name,max=100){if(!Array.isArray(v)||v.length>max)throw Error(`${name}格式不合法`);return v.map(s=>str(s,name,500));}
function articleOf(p){if(!p)throw Error('缺少文章快照');const a={};for(const key of ['id','title','journal','url'])a[key]=str(p[key],key,10000);for(const key of ['doi','abstract','journalId','date','evidenceScope','studyType'])if(p[key]!==undefined)a[key]=str(p[key],key);if(!/^https:\/\//.test(a.url))throw Error('原文链接需为HTTPS');for(const key of ['topics','sources','transferMechanisms'])if(p[key]!==undefined)a[key]=strings(p[key],key);if(p.authors!==undefined){if(!Array.isArray(p.authors)||p.authors.length>2000)throw Error('作者格式无效');a.authors=p.authors.map(x=>({name:str(x.name,'作者',1000),source:str(x.source||'','作者来源',100),affiliations:strings(x.affiliations||[],'作者单位')}));}return a;}
export function validateNote(n){
 if(!n||typeof n.favorite!=='boolean'||!Array.isArray(n.radars)||!n.radars.length||n.radars.some(r=>!['basic','clinical'].includes(r)))throw Error('个人记录结构无效');
 const article=articleOf(n.article);if(n.key!==noteKey(article)||normalizeDOI(n.doi)!==normalizeDOI(article.doi))throw Error('DOI关联不一致');
 const profiles={};for(const radar of ['basic','clinical'])if(n.profiles?.[radar]){const p=n.profiles[radar];for(const k of ['relevance','inspiration'])if(!Number.isInteger(p[k])||p[k]<0||p[k]>5)throw Error('评分须为0–5整数，0为未评分');if(!Number.isFinite(Date.parse(p.updatedAt)))throw Error('评分日期无效');profiles[radar]={relevance:p.relevance,inspiration:p.inspiration,reasons:strings(p.reasons,'关注原因',6),lowReason:str(p.lowReason,'低评分原因',5000),updatedAt:p.updatedAt};}
 if(!['unread','read','deep'].includes(n.readStatus))throw Error('阅读状态无效');for(const k of ['createdAt','updatedAt'])if(!Number.isFinite(Date.parse(n[k])))throw Error('笔记日期无效');
 return {key:noteKey(article),doi:normalizeDOI(n.doi),radars:[...new Set(n.radars)],article,favorite:n.favorite,folder:str(n.folder,'文件夹',200),tags:[...new Set(strings(n.tags,'标签'))],readStatus:n.readStatus,profiles,annotations:str(n.annotations,'批注'),methods:str(n.methods,'方法'),hypotheses:str(n.hypotheses,'假设'),questions:str(n.questions,'待验证问题'),createdAt:n.createdAt,updatedAt:n.updatedAt};
}
export function validatePreference(p){if(!p||!['basic','clinical'].includes(p.radar))throw Error('兴趣画像无效');return {radar:p.radar,approvedKeywords:strings(p.approvedKeywords,'审核关键词'),updatedAt:str(p.updatedAt,'审核时间',100)};}
export function validateBackup(v){if(!v||v.format!=='research-radar-personal'||v.version!==2||!Array.isArray(v.notes)||!Array.isArray(v.preferences)||v.notes.length>10000)throw Error('备份版本或结构不受支持');const notes=v.notes.map(validateNote),preferences=v.preferences.map(validatePreference);if(new Set(notes.map(n=>n.key)).size!==notes.length||new Set(preferences.map(n=>n.radar)).size!==preferences.length)throw Error('备份中主键重复');return {format:v.format,version:2,exportedAt:v.exportedAt,notes,preferences};}
export async function exportBackup(){return {format:'research-radar-personal',version:2,exportedAt:new Date().toISOString(),notes:await allNotes(),preferences:await allPreferences()};}
export function previewRestore(v,existing){const b=validateBackup(v),keys=new Set(existing.map(n=>n.key));return {backup:b,total:b.notes.length,added:b.notes.filter(n=>!keys.has(n.key)).length,overwritten:b.notes.filter(n=>keys.has(n.key)).length,preferences:b.preferences.length};}
// Explicit UI confirmation precedes this one atomic transaction.
export async function restoreBackup(v){const b=validateBackup(v);return transaction(['notes','preferences'],'readwrite',tx=>{for(const n of b.notes)tx.objectStore('notes').put(n);for(const p of b.preferences)tx.objectStore('preferences').put(p);});}
